WITH lines AS (SELECT id, host, level, latency_ms, status_code, key, value FROM app_logs LATERAL VIEW EXPLODE(context) e AS key, value) SELECT id, level, status_code, key, value, FIRST_VALUE(latency_ms, TRUE) OVER (ORDER BY latency_ms ASC, id ASC, key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_latency_ms, CORR(status_code, latency_ms) OVER (PARTITION BY host) AS corr_status_code_latency_ms, SUM(status_code) OVER (PARTITION BY level ORDER BY latency_ms ASC, id ASC, key ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_status_code FROM lines WHERE latency_ms <= 2255;
